    source: `myCPU/tests/host/${name}.cpp`, source_sha256: hash(`${cwd}/tests/host/${name}.cpp`),
    binary_sha256: hash(`${cwd}/tests/host/${name}`), config: 'deterministic embedded fixtures; no xv6 or shared fs image' });
}
entries.push({ evidence_id: 'E-U3-014', argv: ['python3', 'tests/host/run_debug_cli_probe_test.py'], cwd,
  status: 'not-run', reason: 'Default tests include actual xv6 kernel/fs.img probes at lines 1630 and 1676; U4 owns the shared image during this collection.',
  source_sha256: hash(`${cwd}/tests/host/run_debug_cli_probe_test.py`) });
