  collector_source: readFileSync('/tmp/u3-existing-collector.mjs', 'utf8'), collector_argv: [process.execPath, ...process.argv.slice(1)], entries };
writeFileSync(`${root}/docs/reviews/system-software-evidence-c253dda/u3-existing-runs.json`, JSON.stringify(output, null, 2) + '\n');
console.log(JSON.stringify(entries.map(({ evidence_id, exit_code, status, stderr }) => ({ evidence_id, exit_code, status, stderr }))));
